CREATE TABLE IF NOT EXISTS sehatmitra.patient_profiles (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id text NOT NULL, alias text NOT NULL, age_band text NOT NULL CHECK(age_band IN('child','adult','older-adult')), preferred_language text NOT NULL, consent_to_share boolean NOT NULL DEFAULT false, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,alias));
CREATE TABLE IF NOT EXISTS sehatmitra.staff_capacity (capacity_date date NOT NULL, staff_role text NOT NULL CHECK(staff_role IN('asha','doctor','nurse')), available_slots integer NOT NULL CHECK(available_slots BETWEEN 0 AND 500), updated_by text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(capacity_date,staff_role));
